  p.n1 = p.ntile < 256 ? p.ntile : 256; p.n2 = p.ntile - p.n1;
  p.tmem_cols = p.n2 ? 512 : p.n1 <= 32 ? 32 : p.n1 <= 64 ? 64 : p.n1 <= 128 ? 128 : 256;
  p.items = persist ? p.nb : 1; p.fuse = fuse; p.n8 = B * kD / 8;
  const int stageBytes = kABlk + p.ntile / 2 * 128;
  p.stages = (kSmemDyn - 1024) / stageBytes;
  if (p.stages > kMaxStages) p.stages = kMaxStages;
  const int grid = 2 * kPairs * p.nb / p.items;
  if (fuse && (p.items != p.nb || (p.n8 / grid + 1) * 32 > p.stages * stageBytes)) return 434;
  if (!g_sync) { cudaMalloc(&g_sync, 2 * sizeof(unsigned)); cudaMemset(g_sync, 0, 2 * sizeof(unsigned)); cudaDeviceSynchronize(); }
