  cuuint32_t bE1[2] = {kBK, (cuuint32_t)(p.n1 / 2)}, bE2[2] = {kBK, (cuuint32_t)(p.n2 ? p.n2 / 2 : 8)};
  cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  static bool attr_set = false;
